import java.util.*;
public class Employee {
    private final int id;
    private final String name;
    private final String dept;
    public Employee(int id, String name, String dept) {
        this.id = id; this.name = name; this.dept = dept;
    }
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;                       // 1. same reference
        if (o == null || getClass() != o.getClass())      // 2. null / type check
            return false;
        Employee e = (Employee) o;                        // 3. cast
        return id == e.id                                 // 4. compare fields
            && Objects.equals(name, e.name)
            && Objects.equals(dept, e.dept);
    }
    @Override
    public int hashCode() {
        return Objects.hash(id, name, dept);   // same fields as equals()
    }
    @Override
    public String toString() { return id + ":" + name; }
}

public static void main(String[] args) {
    Employee a = new Employee(1, "Asha", "IT");
    Employee b = new Employee(1, "Asha", "IT");
    System.out.println(a == b);              // false
    System.out.println(a.equals(b));         // true
    Set<Employee> set = new HashSet<>(List.of(a));
    System.out.println(set.contains(b));     // true
}

import java.util.*;
public class BrokenKey {
    static class Point {               // equals() overridden, hashCode() NOT
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }
    }
    public static void main(String[] args) {
        Map<Point, String> map = new HashMap<>();
        map.put(new Point(1, 2), "A");
        System.out.println(map.get(new Point(1, 2)));    // null (almost always)
        Set<Point> set = new HashSet<>();
        set.add(new Point(1, 2));
        set.add(new Point(1, 2));
        System.out.println(set.size());                  // 2 -> duplicates!
    }
}

import java.util.*;
public class MutableKey {
    static class Key {
        String value;
        Key(String v) { value = v; }
        @Override public boolean equals(Object o) {
            return o instanceof Key && ((Key) o).value.equals(value);
        }
        @Override public int hashCode() { return value.hashCode(); }
    }
    public static void main(String[] args) {
        Key k = new Key("java");
        Map<Key, Integer> map = new HashMap<>();
        map.put(k, 100);
        k.value = "python";                       // mutate AFTER insertion
        System.out.println(map.get(k));           // null - wrong bucket
        System.out.println(map.get(new Key("java"))); // null - equals fails
        System.out.println(map.size());           // 1 - entry is "lost"
    }
}

import java.util.*;
public class MyArrayList<E> implements Iterable<E> {
    private static final int DEFAULT_CAPACITY = 10;
    private Object[] data;
    private int size;
    private int modCount;                      // for fail-fast iteration
    public MyArrayList() { data = new Object[DEFAULT_CAPACITY]; }
    public void add(E e) {
        ensureCapacity(size + 1);
        data[size++] = e;
        modCount++;
    }
    public void add(int index, E e) {
        if (index < 0 || index > size)
            throw new IndexOutOfBoundsException("Index: " + index);
        ensureCapacity(size + 1);
        System.arraycopy(data, index, data, index + 1, size - index);
        data[index] = e;
        size++;
        modCount++;
    }
    @SuppressWarnings("unchecked")
    public E get(int index) {
        checkIndex(index);
        return (E) data[index];
    }
    @SuppressWarnings("unchecked")
    public E set(int index, E e) {
        checkIndex(index);
        E old = (E) data[index];
        data[index] = e;
        return old;
    }

@SuppressWarnings("unchecked")
public E remove(int index) {
    checkIndex(index);
    E old = (E) data[index];
    int moved = size - index - 1;
    if (moved > 0) System.arraycopy(data, index + 1, data, index, moved);
    data[--size] = null;                   // let GC reclaim
    modCount++;
    return old;
}
public boolean remove(Object o) {
    int i = indexOf(o);
    if (i < 0) return false;
    remove(i);
    return true;
}
public int indexOf(Object o) {
    for (int i = 0; i < size; i++)
        if (Objects.equals(o, data[i])) return i;   // relies on equals()
    return -1;
}
public boolean contains(Object o) { return indexOf(o) >= 0; }
public int size() { return size; }
public boolean isEmpty() { return size == 0; }
private void ensureCapacity(int min) {
    if (min > data.length) {
        int newCap = data.length + (data.length >> 1);   // grow 1.5x
        if (newCap < min) newCap = min;
        data = Arrays.copyOf(data, newCap);
    }
}
private void checkIndex(int i) {
    if (i < 0 || i >= size)
        throw new IndexOutOfBoundsException("Index: " + i + ", Size: " + size);
}

    @Override
    public Iterator<E> iterator() {
        return new Iterator<E>() {
            int cursor = 0;
            int expectedModCount = modCount;
            public boolean hasNext() { return cursor < size; }
            @SuppressWarnings("unchecked")
            public E next() {
                if (modCount != expectedModCount)
                    throw new ConcurrentModificationException();
                if (cursor >= size) throw new NoSuchElementException();
                return (E) data[cursor++];
            }
        };
    }
    @Override
    public String toString() {
        StringJoiner sj = new StringJoiner(", ", "[", "]");
        for (int i = 0; i < size; i++) sj.add(String.valueOf(data[i]));
        return sj.toString();
    }
}

public static void main(String[] args) {
    MyArrayList<String> list = new MyArrayList<>();
    for (int i = 0; i < 12; i++) list.add("e" + i);   // forces a resize
    list.add(0, "first");
    list.remove("e5");
    System.out.println(list.size() + " " + list.get(0) + " " + list.contains("e5"));
    try {
        for (String s : list) if (s.equals("e1")) list.add("x");
    } catch (ConcurrentModificationException ex) {
        System.out.println("Fail-fast: CME thrown");
    }
}

import java.util.*;
public class MyLinkedList<E> implements Iterable<E> {
    private static class Node<E> {
        E val; Node<E> prev, next;
        Node(E val) { this.val = val; }
    }
    private Node<E> head, tail;
    private int size;
    public void addFirst(E e) {
        Node<E> n = new Node<>(e);
        if (head == null) { head = tail = n; }
        else { n.next = head; head.prev = n; head = n; }
        size++;
    }
    public void addLast(E e) {
        Node<E> n = new Node<>(e);
        if (tail == null) { head = tail = n; }
        else { tail.next = n; n.prev = tail; tail = n; }
        size++;
    }
    public E removeFirst() {
        if (head == null) throw new NoSuchElementException();
        E v = head.val;
        unlink(head);
        return v;
    }
    public boolean remove(Object o) {
        for (Node<E> n = head; n != null; n = n.next)
            if (Objects.equals(o, n.val)) { unlink(n); return true; }
        return false;
    }
    private void unlink(Node<E> n) {
        if (n.prev == null) head = n.next; else n.prev.next = n.next;

    if (n.next == null) tail = n.prev; else n.next.prev = n.prev;
    n.prev = n.next = null;
    size--;
}
public E get(int index) {
    if (index < 0 || index >= size) throw new IndexOutOfBoundsException();
    Node<E> n;
    if (index < size / 2) {                       // walk from closer end
        n = head; for (int i = 0; i < index; i++) n = n.next;
    } else {
        n = tail; for (int i = size - 1; i > index; i--) n = n.prev;
    }
    return n.val;
}
public void reverse() {
    Node<E> cur = head, tmp = null;
    tail = head;
    while (cur != null) {
        tmp = cur.prev;
        cur.prev = cur.next;
        cur.next = tmp;
        cur = cur.prev;
    }
    if (tmp != null) head = tmp.prev;
}
public int size() { return size; }
@Override
public Iterator<E> iterator() {
    return new Iterator<E>() {
        Node<E> cur = head;
        public boolean hasNext() { return cur != null; }
        public E next() {
            if (cur == null) throw new NoSuchElementException();
            E v = cur.val; cur = cur.next; return v;
        }
    };

    }
    @Override
    public String toString() {
        StringJoiner sj = new StringJoiner(" <-> ", "[", "]");
        for (E e : this) sj.add(String.valueOf(e));
        return sj.toString();
    }
}

public static void main(String[] args) {
    MyLinkedList<Integer> l = new MyLinkedList<>();
    l.addLast(2); l.addLast(3); l.addFirst(1); l.addLast(4);
    System.out.println(l + " get(2)=" + l.get(2));
    l.reverse();
    System.out.println(l);
    l.remove(Integer.valueOf(3));
    System.out.println(l + " size=" + l.size());
}

import java.util.*;
public class MyHashMap<K, V> {
    static class Entry<K, V> {
        final K key; final int hash; V value; Entry<K, V> next;
        Entry(int hash, K key, V value, Entry<K, V> next) {
            this.hash = hash; this.key = key; this.value = value; this.next = next;
        }
    }
    private static final float LOAD_FACTOR = 0.75f;
    private Entry<K, V>[] table;
    private int size;
    @SuppressWarnings("unchecked")
    public MyHashMap() { table = (Entry<K, V>[]) new Entry[16]; }   // power of 2
    // Spread high bits into low bits, like java.util.HashMap
    private static int hash(Object key) {
        if (key == null) return 0;
        int h = key.hashCode();
        return h ^ (h >>> 16);
    }
    private static int indexFor(int hash, int length) {
        return hash & (length - 1);        // same as hash % length when length is 2^n
    }
    public V put(K key, V value) {
        int h = hash(key);
        int i = indexFor(h, table.length);
        for (Entry<K, V> e = table[i]; e != null; e = e.next) {
            if (e.hash == h && Objects.equals(e.key, key)) {    // hashCode THEN equals
                V old = e.value;
                e.value = value;                               // replace existing
                return old;
            }
        }
        table[i] = new Entry<>(h, key, value, table[i]);       // insert at head
        if (++size > table.length * LOAD_FACTOR) resize();

    return null;
}
public V get(Object key) {
    int h = hash(key);
    for (Entry<K, V> e = table[indexFor(h, table.length)]; e != null; e = e.next)
        if (e.hash == h && Objects.equals(e.key, key)) return e.value;
    return null;
}
public boolean containsKey(Object key) {
    int h = hash(key);
    for (Entry<K, V> e = table[indexFor(h, table.length)]; e != null; e = e.next)
        if (e.hash == h && Objects.equals(e.key, key)) return true;
    return false;
}
public V remove(Object key) {
    int h = hash(key);
    int i = indexFor(h, table.length);
    Entry<K, V> prev = null;
    for (Entry<K, V> e = table[i]; e != null; prev = e, e = e.next) {
        if (e.hash == h && Objects.equals(e.key, key)) {
            if (prev == null) table[i] = e.next; else prev.next = e.next;
            size--;
            return e.value;
        }
    }
    return null;
}
@SuppressWarnings("unchecked")
private void resize() {
    Entry<K, V>[] old = table;
    table = (Entry<K, V>[]) new Entry[old.length * 2];
    for (Entry<K, V> head : old) {
        for (Entry<K, V> e = head; e != null; ) {
            Entry<K, V> next = e.next;
            int i = indexFor(e.hash, table.length);   // rehash into new table
            e.next = table[i];

                table[i] = e;
                e = next;
            }
        }
    }
    public int size() { return size; }
    public Set<K> keySet() {
        Set<K> keys = new HashSet<>();
        for (Entry<K, V> head : table)
            for (Entry<K, V> e = head; e != null; e = e.next) keys.add(e.key);
        return keys;
    }
}

public static void main(String[] args) {
    MyHashMap<String, Integer> m = new MyHashMap<>();
    for (int i = 0; i < 100; i++) m.put("k" + i, i);    // triggers resizes
    m.put("k5", 500);                                   // overwrite
    m.put(null, -1);                                    // null key allowed
    System.out.println(m.size() + " " + m.get("k5") + " " + m.get(null));
    m.remove("k5");
    System.out.println(m.containsKey("k5") + " " + m.size());
    // "Aa" and "BB" have the SAME hashCode (2112) -> collision in one bucket
    m.put("Aa", 1); m.put("BB", 2);
    System.out.println("Aa".hashCode() + " " + "BB".hashCode() + " "
            + m.get("Aa") + " " + m.get("BB"));
}

import java.util.*;
public class MyHashSet<E> implements Iterable<E> {
    private static final Object PRESENT = new Object();   // dummy value
    private final MyHashMap<E, Object> map = new MyHashMap<>();
    public boolean add(E e)          { return map.put(e, PRESENT) == null; }
    public boolean remove(Object o)  { return map.remove(o) == PRESENT; }
    public boolean contains(Object o){ return map.containsKey(o); }
    public int size()                { return map.size(); }
    public Iterator<E> iterator()    { return map.keySet().iterator(); }
    public static void main(String[] args) {
        MyHashSet<Employee> set = new MyHashSet<>();
        System.out.println(set.add(new Employee(1, "Asha", "IT")));   // true
        System.out.println(set.add(new Employee(1, "Asha", "IT")));   // false - duplicate
        System.out.println(set.size() + " " + set.contains(new Employee(1, "Asha", "IT")));
    }
}

import java.util.*;
// Approach 1: extend LinkedHashMap (access-order)
class LRUCacheSimple<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;
    LRUCacheSimple(int capacity) {
        super(capacity, 0.75f, true);          // true = access order
        this.capacity = capacity;
    }
    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;
    }
}
// Approach 2: HashMap + doubly linked list, O(1) get/put
public class LRUCache {
    private static class Node {
        int key, val; Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(0, 0), tail = new Node(0, 0);  // sentinels
    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail; tail.prev = head;
    }
    public int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        moveToFront(n);
        return n.val;
    }
    public void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) { n.val = value; moveToFront(n); return; }

        if (map.size() == capacity) {
            Node lru = tail.prev;              // least recently used
            unlink(lru);
            map.remove(lru.key);
        }
        n = new Node(key, value);
        map.put(key, n);
        addFront(n);
    }
    private void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    private void addFront(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
    private void moveToFront(Node n) { unlink(n); addFront(n); }
}

public static void main(String[] args) {
    LRUCache c = new LRUCache(2);
    c.put(1, 1); c.put(2, 2);
    System.out.println(c.get(1));   // 1
    c.put(3, 3);                    // evicts key 2
    System.out.println(c.get(2));   // -1
    c.put(4, 4);                    // evicts key 1
    System.out.println(c.get(1) + " " + c.get(3) + " " + c.get(4));   // -1 3 4
    LRUCacheSimple<String, Integer> s = new LRUCacheSimple<>(2);
    s.put("a", 1); s.put("b", 2); s.get("a"); s.put("c", 3);
    System.out.println(s.keySet());  // [a, c]
}

import java.util.*;
public class TreeSetEquals {
    record Person(String name, int age) {}       // record: equals/hashCode auto-generated
    public static void main(String[] args) {
        Comparator<Person> byAge = Comparator.comparingInt(Person::age);
        Set<Person> tree = new TreeSet<>(byAge);
        tree.add(new Person("Ravi", 30));
        tree.add(new Person("Meena", 30));        // compare() == 0 -> treated as duplicate!
        System.out.println(tree.size());          // 1
        Set<Person> hash = new HashSet<>();
        hash.add(new Person("Ravi", 30));
        hash.add(new Person("Meena", 30));
        System.out.println(hash.size());          // 2
        // Fix: make comparator consistent with equals
        Set<Person> fixed = new TreeSet<>(byAge.thenComparing(Person::name));
        fixed.add(new Person("Ravi", 30));
        fixed.add(new Person("Meena", 30));
        System.out.println(fixed);
    }
}

static Character firstUnique(String s) {
    Map<Character, Integer> freq = new LinkedHashMap<>();   // keeps insertion order
    for (char c : s.toCharArray()) freq.merge(c, 1, Integer::sum);
    for (Map.Entry<Character, Integer> e : freq.entrySet())
        if (e.getValue() == 1) return e.getKey();
    return null;
}

static Collection<List<String>> groupAnagrams(String[] words) {
    Map<String, List<String>> groups = new HashMap<>();
    for (String w : words) {
        char[] c = w.toCharArray();
        Arrays.sort(c);
        groups.computeIfAbsent(new String(c), k -> new ArrayList<>()).add(w);
    }
    return groups.values();
}

static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);
        if (j != null) return new int[]{j, i};
        seen.put(nums[i], i);
    }
    return new int[0];
}

static <T> List<T> dedupe(List<T> in) {
    return new ArrayList<>(new LinkedHashSet<>(in));
}

static List<Integer> topK(int[] nums, int k) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int n : nums) freq.merge(n, 1, Integer::sum);
    PriorityQueue<Map.Entry<Integer, Integer>> pq =
        new PriorityQueue<>(Map.Entry.comparingByValue());     // min-heap by count
    for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
        pq.offer(e);
        if (pq.size() > k) pq.poll();
    }
    List<Integer> res = new ArrayList<>();
    while (!pq.isEmpty()) res.add(pq.poll().getKey());
    Collections.reverse(res);
    return res;
}

static LinkedHashMap<String, Integer> sortByValue(Map<String, Integer> m) {
    return m.entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue,
                    (a, b) -> a, LinkedHashMap::new));
}

static List<Integer> intersect(int[] a, int[] b) {
    Map<Integer, Integer> cnt = new HashMap<>();
    for (int x : a) cnt.merge(x, 1, Integer::sum);
    List<Integer> res = new ArrayList<>();
    for (int x : b) {
        Integer c = cnt.get(x);
        if (c != null && c > 0) { res.add(x); cnt.put(x, c - 1); }
    }
    return res;
}

static int longestUnique(String s) {
    Map<Character, Integer> last = new HashMap<>();
    int best = 0, start = 0;
    for (int i = 0; i < s.length(); i++) {
        Integer prev = last.put(s.charAt(i), i);
        if (prev != null && prev >= start) start = prev + 1;
        best = Math.max(best, i - start + 1);
    }
    return best;
}

static void removeEvens(List<Integer> list) {
    Iterator<Integer> it = list.iterator();
    while (it.hasNext()) if (it.next() % 2 == 0) it.remove();
    // Java 8+: list.removeIf(n -> n % 2 == 0);
}

static Map<String, Long> countByDept(List<String[]> emps) {
    return emps.stream()
               .collect(Collectors.groupingBy(e -> e[1], TreeMap::new, Collectors.counting()));
}

