public class MathUtil {
    public static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i * i <= n; i++) if (n % i == 0) return false;
        return true;
    }
}

List<Integer> primes = IntStream.rangeClosed(1, 20).boxed()
        .filter(MathUtil::isPrime)          // n -> MathUtil.isPrime(n)
        .collect(Collectors.toList());     // [2, 3, 5, 7, 11, 13, 17, 19]

