Object obj = clazz.getDeclaredConstructor().newInstance();
Field f = clazz.getDeclaredField("name");
f.setAccessible(true);
f.set(obj, "Ravi");
Method m = clazz.getMethod("greet");
m.invoke(obj);
for (Method mm : clazz.getDeclaredMethods())
    if (mm.isAnnotationPresent(Deprecated.class)) System.out.println(mm.getName());

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
@interface Timed { String value() default ""; }

class Service {
    @Timed("load-users")
    void loadUsers() { }
}
for (Method m : Service.class.getDeclaredMethods()) {
    Timed t = m.getAnnotation(Timed.class);
    if (t != null) System.out.println("Timing " + t.value());
}
